def make_doc(words, ents):
    """ents: list of (start_token, end_token, label). Returns a Doc with .ents set."""
    nlp = spacy.blank("en")
    doc = spacy.tokens.Doc(nlp.vocab, words=words, spaces=[True] * len(words))
    doc.ents = [Span(doc, s, e, label=lbl) for s, e, lbl in ents]
    return doc


def test_valid_entities_pass_through():
    doc = make_doc(["TP53", "mutation", "causes", "cancer"],
                   [(0, 1, "GENE"), (3, 4, "DISEASE")])
    out = NERTagger.from_doc(doc)
    assert [e["text"] for e in out] == ["TP53", "cancer"]
    assert out[0]["label"] == "GENE"
    assert out[0]["normalized"] == "tp53"
    assert out[0]["start"] == 0 and out[0]["end"] == 4
    assert out[0]["negated"] is False
    assert out[0]["assertion"] == "PRESENT"
    print("✓ valid entities pass through with correct fields")


def test_invalid_spans_filtered():
    # "[Ca" is bracket-leading, "12" is numeric-only, "x" is <2 chars.
    doc = make_doc(["[Ca", "12", "x", "BRCA1"],
                   [(0, 1, "OTHER"), (1, 2, "OTHER"), (2, 3, "OTHER"), (3, 4, "GENE")])
    out = NERTagger.from_doc(doc)
    assert [e["text"] for e in out] == ["BRCA1"]
    print("✓ bracket-leading / numeric / too-short spans filtered")


def test_dedup_by_normalized_text_and_offset():
    # Same normalized text at two DIFFERENT offsets -> both kept (distinct mentions).
    doc = make_doc(["EGFR", "and", "egfr", "differ"],
                   [(0, 1, "GENE"), (2, 3, "GENE")])
    out = NERTagger.from_doc(doc)
    assert [(e["text"], e["start"]) for e in out] == [("EGFR", 0), ("egfr", 9)]
    print("✓ repeat mentions at distinct offsets are both kept")


def test_score_and_source_defaults_without_extensions():
    doc = make_doc(["insulin"], [(0, 1, "PROTEIN")])
    out = NERTagger.from_doc(doc)
    assert out[0]["ner_confidence"] == 1.0
    assert out[0]["source"] == ""
    print("✓ missing score/source extensions default to 1.0 / ''")


def test_score_and_source_read_from_extensions():
    if not Span.has_extension("score"):
        Span.set_extension("score", default=1.0)
    if not Span.has_extension("source"):
        Span.set_extension("source", default="")
    nlp = spacy.blank("en")
    doc = spacy.tokens.Doc(nlp.vocab, words=["insulin"], spaces=[True])
    span = Span(doc, 0, 1, label="PROTEIN")
    span._.score = 0.876
    span._.source = "gliner_large"
    doc.ents = [span]
    out = NERTagger.from_doc(doc)
    assert out[0]["ner_confidence"] == 0.876
    assert out[0]["source"] == "gliner_large"
    print("✓ score/source read from span extensions when registered")


if __name__ == "__main__":
    test_valid_entities_pass_through()
    test_invalid_spans_filtered()
    test_dedup_by_normalized_text_and_offset()
    test_score_and_source_defaults_without_extensions()
    test_score_and_source_read_from_extensions()
    print("\nAll NERTagger tests passed.")
